using System;using System.IO;using UnityEngine;using UnityEditor;
public static class RecoveredNativePost {
 [Serializable] public class Row {public string name;public Vector4 value;}
 [Serializable] public class Data {public Row[] vectors;}
 const string Dst="Assets/RecoveredS07/Environment/";
 public static void Import(Camera camera){
  var shader=Shader.Find("Recovered/Hidden/FX/ColorGradingHDR/Variant1");if(shader==null||ShaderUtil.ShaderHasError(shader))throw new InvalidOperationException("Original HDR shader port failed to compile");
  var builder=new Material(shader);var data=JsonUtility.FromJson<Data>(File.ReadAllText("Assets/Recovery/NativeScene/post-parameters.json"));foreach(var row in data.vectors)builder.SetVector(row.name,row.value);
  var rt=RenderTexture.GetTemporary(1024,32,0,RenderTextureFormat.ARGBHalf,RenderTextureReadWrite.Linear);var previous=RenderTexture.active;
  Graphics.Blit(Texture2D.blackTexture,rt,builder,0);RenderTexture.active=rt;var lut=new Texture2D(1024,32,TextureFormat.RGBAHalf,false,true){name="NativeACES_ColorGradingLUT",filterMode=FilterMode.Bilinear,wrapMode=TextureWrapMode.Clamp};lut.ReadPixels(new Rect(0,0,1024,32),0,0,false);lut.Apply(false,false);RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(builder);
  Save(lut,Dst+"NativeACES_LUT.asset");var composite=new Material(Shader.Find("Recovered/Hidden/FX/Uber/Variant3")){name="NativeHDRComposite"};composite.SetTexture("_Lut2D",lut);composite.SetVector("_Lut2D_Params",new Vector4(1f/1024,1f/32,31,0));composite.SetFloat("_PostExposure",1);composite.SetFloat("_BloomIntensity",0);composite.SetTexture("_BloomTex",Texture2D.blackTexture);composite.SetVector("rectRenderClipBloom",new Vector4(0,0,1,1));Save(composite,Dst+"NativeHDRComposite.mat");camera.allowHDR=true;var post=camera.gameObject.AddComponent<RecoveredPostProcessing>();post.composite=composite;
  foreach(var name in new[]{"Sharpen","Copy"}){var shaderFX=Shader.Find("Recovered/Hidden/FX/"+name+"/Variant1");if(shaderFX==null||ShaderUtil.ShaderHasError(shaderFX))throw new InvalidOperationException("Native post shader failed: "+name);var materialFX=new Material(shaderFX){name="Native"+name};Save(materialFX,Dst+"Native"+name+".mat");if(name=="Sharpen")post.sharpen=materialFX;else post.copy=materialFX;}
  var fxaaShader=Shader.Find("Recovered/Hidden/FX/FXAA/Variant3");if(fxaaShader==null||ShaderUtil.ShaderHasError(fxaaShader))throw new InvalidOperationException("Native FXAA fast shader failed");post.fxaa=new Material(fxaaShader){name="NativeFXAAFast"};Save(post.fxaa,Dst+"NativeFXAAFast.mat");var overlay=camera.gameObject.AddComponent<RecoveredOverlayRenderer>();var renderers=new System.Collections.Generic.List<Renderer>();foreach(var renderer in UnityEngine.Object.FindObjectsOfType<Renderer>())if(renderer.gameObject.layer==8)renderers.Add(renderer);overlay.overlays=renderers.ToArray();post.bloomPasses=new Material[4];int[] variants={2,5,6,9};for(int i=0;i<variants.Length;i++){var bloomShader=Shader.Find("Recovered/Hidden/FX/Bloom/Variant"+variants[i]);if(bloomShader==null||ShaderUtil.ShaderHasError(bloomShader))throw new InvalidOperationException("Bloom shader port failed: "+variants[i]);var material=new Material(bloomShader){name="NativeBloomPass"+i};material.SetFloat("_BloomThreshold",4.5947938f);material.SetFloat("_PrefilterOffs",0);Save(material,Dst+"NativeBloomPass"+i+".mat");post.bloomPasses[i]=material;}
 }
 static void Save(UnityEngine.Object obj,string path){AssetDatabase.DeleteAsset(path);AssetDatabase.CreateAsset(obj,path);}
}
